     1|/**
     2| * IVX Autonomous SMS Notifier — sends owner status updates via AWS SNS.
     3| *
     4| * Wired into the autonomous scheduler tick. Every 2 hours, sends a concise
     5| * status SMS to the owner's phone (IVX_OWNER_RECOVERY_PHONE) with:
     6| *   - 12-IA agent active count
     7| *   - Factory agent pending/active count
     8| *   - Queue depth
     9| *   - Any blockers
    10| *
    11| * HONESTY RULES:
    12| *   - Never sends fabricated status. Counts come from live Supabase rows.
    13| *   - If Supabase is unreachable, the SMS says "DB unreachable" — not fake zeros.
    14| *   - Rate-limited to 1 SMS per 2 hours (12 per day max).
    15| *   - If AWS SNS is not configured or fails, tries Twilio (IVX_TWILIO_* env vars).
    16| *   - If both transports fail, logs a warning and skips — never throws.
    17| *
    18| * Marker: ivx-autonomous-sms-notifier-2026-08-11
    19| */
    20|import { sendSnsSms, resolveOwnerRecoveryPhone, type SnsSmsResult } from './ivx-sns-sms';
    21|import { sendTwilioSms, isTwilioSmsConfigured, type TwilioSmsResult } from './ivx-twilio-sms';
    22|
    23|export const IVX_SMS_NOTIFIER_MARKER = 'ivx-autonomous-sms-notifier-2026-08-11';
    24|const NOTIFICATION_INTERVAL_MS = 2 * 60 * 60 * 1000; // 2 hours
    25|const MAX_SMS_PER_DAY = 12;
    26|
    27|let lastSmsSentAt = 0;
    28|let smsSentToday = 0;
    29|let smsDayResetAt = Date.now() + 24 * 60 * 60 * 1000;
    30|let timer: ReturnType<typeof setInterval> | null = null;
    31|
    32|type StatusCounts = {
    33|  agentsActive: number | null;
    34|  agentsTotal: number | null;
    35|  factoryPending: number | null;
    36|  factoryActive: number | null;
    37|  queueDepth: number | null;
    38|  runningTasks: number | null;
    39|  blockedTasks: number | null;
    40|  databaseReachable: boolean;
    41|};
    42|
    43|/**
    44| * Fetch live counts from the IA orchestrator's Supabase queries.
    45| * Uses the same REST API pattern as ivx-ia-orchestrator.ts.
    46| */
    47|async function fetchLiveCounts(): Promise<StatusCounts> {
    48|  const supabaseUrl = (process.env.IVX_SUPABASE_URL || process.env.SUPABASE_URL || process.env.EXPO_PUBLIC_SUPABASE_URL || '').trim().replace(/\/$/, '');
    49|  const serviceKey = (process.env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
    50|
    51|  if (!supabaseUrl || !serviceKey) {
    52|    return {
    53|      agentsActive: null,
    54|      agentsTotal: null,
    55|      factoryPending: null,
    56|      factoryActive: null,
    57|      queueDepth: null,
    58|      runningTasks: null,
    59|      blockedTasks: null,
    60|      databaseReachable: false,
    61|    };
    62|  }
    63|
    64|  try {
    65|    const headers: Record<string, string> = {
    66|      apikey: serviceKey,
    67|      Authorization: `Bearer ${serviceKey}`,
    68|      'Content-Type': 'application/json',
    69|      Prefer: 'count=exact',
    70|    };
    71|
    72|    const fetchCount = async (path: string): Promise<number | null> => {
    73|      try {
    74|        const res = await fetch(`${supabaseUrl}${path}&select=id&limit=1`, {
    75|          headers,
    76|          signal: AbortSignal.timeout(8000),
    77|        });
    78|        const range = res.headers.get('content-range') ?? '';
    79|        const total = range.includes('/') ? Number(range.split('/')[1]) : NaN;
    80|        return Number.isFinite(total) ? total : null;
    81|      } catch {
    82|        return null;
    83|      }
    84|    };
    85|
    86|    const [agentsTotal, agentsActive, factoryPending, factoryActive, tasksRunning, tasksBlocked, tasksTotal] = await Promise.all([
    87|      fetchCount('/rest/v1/ivx_ia_agents?select=id'),
    88|      fetchCount('/rest/v1/ivx_ia_agents?status=eq.ACTIVE&select=id'),
    89|      fetchCount('/rest/v1/ivx_ia_factory_agents?activation_status=eq.PENDING_OWNER_APPROVAL&select=id'),
    90|      fetchCount('/rest/v1/ivx_ia_factory_agents?activation_status=eq.ACTIVE&select=id'),
    91|      fetchCount('/rest/v1/ivx_ia_tasks?status=eq.RUNNING&select=id'),
    92|      fetchCount('/rest/v1/ivx_ia_tasks?status=eq.BLOCKED&select=id'),
    93|      fetchCount('/rest/v1/ivx_ia_tasks?select=id'),
    94|    ]);
    95|
    96|    return {
    97|      agentsActive,
    98|      agentsTotal,
    99|      factoryPending,
   100|      factoryActive,
   101|      queueDepth: tasksTotal,
   102|      runningTasks: tasksRunning,
   103|      blockedTasks: tasksBlocked,
   104|      databaseReachable: agentsTotal !== null,
   105|    };
   106|  } catch {
   107|    return {
   108|      agentsActive: null,
   109|      agentsTotal: null,
   110|      factoryPending: null,
   111|      factoryActive: null,
   112|      queueDepth: null,
   113|      runningTasks: null,
   114|      blockedTasks: null,
   115|      databaseReachable: false,
   116|    };
   117|  }
   118|}
   119|
   120|/**
   121| * Build a concise SMS body (GSM-7 safe, under 160 chars).
   122| */
   123|function buildStatusSms(counts: StatusCounts): string {
   124|  const db = counts.databaseReachable ? 'OK' : 'DOWN';
   125|  const ia = counts.agentsActive !== null ? `${counts.agentsActive}/${counts.agentsTotal}` : 'n/a';
   126|  const af = counts.factoryPending !== null ? `pend:${counts.factoryPending} active:${counts.factoryActive}` : 'n/a';
   127|  const q = counts.queueDepth !== null ? `q:${counts.queueDepth}` : 'q:n/a';
   128|  const run = counts.runningTasks !== null ? `run:${counts.runningTasks}` : '';
   129|  const blk = counts.blockedTasks && counts.blockedTasks > 0 ? ` BLK:${counts.blockedTasks}` : '';
   130|  return `IVX 24/7: db=${db} IA=${ia} AF=${af} ${q}${run}${blk}`;
   131|}
   132|
   133|/**
   134| * Send a status SMS to the owner. Returns the SNS result.
   135| */
   136|export async function sendOwnerStatusSms(): Promise<SnsSmsResult> {
   137|  const phone = resolveOwnerRecoveryPhone();
   138|  if (!phone) {
   139|    console.warn('[IVX-SMS-Notifier] No owner phone configured — skipping SMS');
   140|    return {
   141|      ok: false,
   142|      status: 'missing_config',
   143|      missingEnvNames: ['IVX_OWNER_RECOVERY_PHONE'],
   144|      error: 'No owner phone configured',
   145|      sentAt: new Date().toISOString(),
   146|    };
   147|  }
   148|
   149|  const counts = await fetchLiveCounts();
   150|  const message = buildStatusSms(counts);
   151|  let result: SnsSmsResult | TwilioSmsResult = await sendSnsSms({ to: phone, message, senderId: 'IVX' });
   152|
   153|  if (!result.ok && isTwilioSmsConfigured()) {
   154|    console.log('[IVX-SMS-Notifier] SNS failed, attempting Twilio fallback...');
   155|    result = await sendTwilioSms({ to: phone, message });
   156|  }
   157|
   158|  if (result.ok) {
   159|    lastSmsSentAt = Date.now();
   160|    smsSentToday += 1;
   161|    console.log('[IVX-SMS-Notifier] Status SMS sent to', phone.slice(0, 2) + '***' + phone.slice(-4), '— message:', message);
   162|  } else {
   163|    console.warn('[IVX-SMS-Notifier] SMS send failed:', result.status, result.error?.slice(0, 100));
   164|  }
   165|
   166|  return result;
   167|}
   168|
   169|/**
   170| * Send an immediate alert SMS (e.g. blocker, failure, factory milestone).
   171| * Bypasses the 2-hour interval but still respects daily cap.
   172| */
   173|export async function sendOwnerAlertSms(alertMessage: string): Promise<SnsSmsResult> {
   174|  const phone = resolveOwnerRecoveryPhone();
   175|  if (!phone) {
   176|    return {
   177|      ok: false,
   178|      status: 'missing_config',
   179|      missingEnvNames: ['IVX_OWNER_RECOVERY_PHONE'],
   180|      error: 'No owner phone configured',
   181|      sentAt: new Date().toISOString(),
   182|    };
   183|  }
   184|
   185|  // Reset daily counter if needed
   186|  if (Date.now() > smsDayResetAt) {
   187|    smsSentToday = 0;
   188|    smsDayResetAt = Date.now() + 24 * 60 * 60 * 1000;
   189|  }
   190|
   191|  if (smsSentToday >= MAX_SMS_PER_DAY) {
   192|    console.warn('[IVX-SMS-Notifier] Daily SMS cap reached — skipping alert');
   193|    return {
   194|      ok: false,
   195|      status: 'rate_limited',
   196|      missingEnvNames: [],
   197|      error: 'Daily SMS cap reached',
   198|      sentAt: new Date().toISOString(),
   199|    };
   200|  }
   201|
   202|  const truncated = alertMessage.slice(0, 140);
   203|  let result: SnsSmsResult | TwilioSmsResult = await sendSnsSms({ to: phone, message: `IVX ALERT: ${truncated}`, senderId: 'IVX' });
   204|
   205|  if (!result.ok && isTwilioSmsConfigured()) {
   206|    console.log('[IVX-SMS-Notifier] SNS alert failed, attempting Twilio fallback...');
   207|    result = await sendTwilioSms({ to: phone, message: `IVX ALERT: ${truncated}` });
   208|  }
   209|
   210|  if (result.ok) {
   211|    smsSentToday += 1;
   212|    console.log('[IVX-SMS-Notifier] Alert SMS sent:', truncated.slice(0, 60));
   213|  }
   214|
   215|  return result;
   216|}
   217|
   218|/**
   219| * Start the autonomous SMS notification scheduler.
   220| * Sends a status SMS every 2 hours. Idempotent.
   221| */
   222|export function startSmsNotificationScheduler(): void {
   223|  if (timer) return;
   224|
   225|  // Send an initial status SMS 30 seconds after boot
   226|  const bootKick = setTimeout(() => {
   227|    void sendOwnerStatusSms().catch((err) => {
   228|      console.warn('[IVX-SMS-Notifier] Boot SMS failed:', err instanceof Error ? err.message : err);
   229|    });
   230|  }, 30_000);
   231|  if (typeof bootKick.unref === 'function') bootKick.unref();
   232|
   233|  // Then every 2 hours
   234|  timer = setInterval(() => {
   235|    // Reset daily counter if needed
   236|    if (Date.now() > smsDayResetAt) {
   237|      smsSentToday = 0;
   238|      smsDayResetAt = Date.now() + 24 * 60 * 60 * 1000;
   239|    }
   240|
   241|    if (smsSentToday >= MAX_SMS_PER_DAY) {
   242|      console.warn('[IVX-SMS-Notifier] Daily SMS cap reached — skipping scheduled SMS');
   243|      return;
   244|    }
   245|
   246|    if (Date.now() - lastSmsSentAt < NOTIFICATION_INTERVAL_MS - 60_000) {
   247|      return; // Too soon since last SMS
   248|    }
   249|
   250|    void sendOwnerStatusSms().catch((err) => {
   251|      console.warn('[IVX-SMS-Notifier] Scheduled SMS failed:', err instanceof Error ? err.message : err);
   252|    });
   253|  }, NOTIFICATION_INTERVAL_MS);
   254|
   255|  if (typeof timer.unref === 'function') timer.unref();
   256|  console.log('[IVX-SMS-Notifier] SMS notification scheduler started (2h interval, boot kick armed)');
   257|}
   258|
   259|export function stopSmsNotificationScheduler(): void {
   260|  if (timer) {
   261|    clearInterval(timer);
   262|    timer = null;
   263|  }
   264|}
   265|
   266|/**
   267| * Get current SMS notifier state (for health/dashboard).
   268| */
   269|export function getSmsNotifierStatus(): {
   270|  marker: string;
   271|  phoneConfigured: boolean;
   272|  twilioConfigured: boolean;
   273|  phoneMasked: string | null;
   274|  lastSmsSentAt: string | null;
   275|  smsSentToday: number;
   276|  smsDailyCap: number;
   277|  schedulerRunning: boolean;
   278|} {
   279|  const phone = resolveOwnerRecoveryPhone();
   280|  return {
   281|    marker: IVX_SMS_NOTIFIER_MARKER,
   282|    phoneConfigured: Boolean(phone),
   283|    twilioConfigured: isTwilioSmsConfigured(),
   284|    phoneMasked: phone ? `${phone.slice(0, 2)}***${phone.slice(-4)}` : null,
   285|    lastSmsSentAt: lastSmsSentAt > 0 ? new Date(lastSmsSentAt).toISOString() : null,
   286|    smsSentToday,
   287|    smsDailyCap: MAX_SMS_PER_DAY,
   288|    schedulerRunning: Boolean(timer),
   289|  };
   290|}

